"use client"

import {
  forwardRef,
  useCallback,
  useId,
  useImperativeHandle,
  useRef,
  useState,
  type KeyboardEvent,
  type ReactNode,
} from "react"

import type { Country } from "./countries"
import { usePhoneInput, type UsePhoneInputOptions } from "./use-phone-input"

export interface PhoneInputProps extends UsePhoneInputOptions {
  /** Visible label. Supply this or `aria-label` — a field with neither has no accessible name. */
  label?: ReactNode
  /** Helper text under the field. Replaced by the error message while one is showing. */
  hint?: ReactNode
  /** Override the country trigger and popover. */
  renderCountry?: (api: {
    country: Country | undefined
    available: readonly Country[]
    setCountry: (iso: string) => void
    disabled: boolean | undefined
  }) => ReactNode
}

// Static JSX hoisted out of the component (rendering-hoist-jsx).
const CARET = (
  <svg
    className="inputcn-caret"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2"
    aria-hidden="true"
  >
    <path d="m6 9 6 6 6-6" />
  </svg>
)

/**
 * A phone field with a searchable country selector, live national formatting
 * and E.164 output.
 *
 * The forwarded ref points at the NUMBER input, not the wrapper — react-hook-form
 * calls `ref.focus()` on the first invalid field and a ref to a <div> silently
 * does nothing. PRD §10.3.
 */
export const PhoneInput = forwardRef<HTMLInputElement, PhoneInputProps>(
  function PhoneInput({ label, hint, renderCountry, className, id: idProp, ...rest }, ref) {
    const reactId = useId()
    const id = idProp ?? reactId

    const api = usePhoneInput({ ...rest, id })
    const {
      country,
      available,
      setCountry,
      inputProps,
      ariaProps,
      containerProps,
      hiddenInputProps,
      ownsErrorUI,
      errorText,
      errorId,
      visible,
      sideEffect,
      undoPaste,
      dismissSideEffect,
    } = api

    useImperativeHandle(
      ref,
      () => {
        const el = inputProps.ref.current
        // Expose the real node so RHF gets focus(), name, value and selection
        // APIs — but guarantee focus() exists even before mount.
        return (el ??
          ({ focus: () => inputProps.ref.current?.focus() } as HTMLInputElement))
      },
      [inputProps.ref],
    )

    /* -------- country popover -------- */
    const [open, setOpen] = useState(false)
    const [query, setQuery] = useState("")
    const [active, setActive] = useState(0)
    const triggerRef = useRef<HTMLButtonElement>(null)

    const q = query.trim().toLowerCase()
    const matches = q
      ? available.filter(
          (c) =>
            c.name.toLowerCase().includes(q) ||
            c.iso.toLowerCase().includes(q) ||
            c.dial.includes(q),
        )
      : available

    const close = useCallback(() => {
      setOpen(false)
      setQuery("")
      setActive(0)
      triggerRef.current?.focus()
    }, [])

    const choose = useCallback(
      (iso: string) => {
        setCountry(iso)
        setOpen(false)
        setQuery("")
        setActive(0)
        inputProps.ref.current?.focus()
      },
      [setCountry, inputProps.ref],
    )

    const onSearchKeyDown = useCallback(
      (e: KeyboardEvent<HTMLInputElement>) => {
        if (e.key === "ArrowDown") {
          e.preventDefault()
          setActive((i) => Math.min(i + 1, matches.length - 1))
        } else if (e.key === "ArrowUp") {
          e.preventDefault()
          setActive((i) => Math.max(i - 1, 0))
        } else if (e.key === "Enter") {
          e.preventDefault()
          const pick = matches[active]
          if (pick) choose(pick.iso)
        } else if (e.key === "Escape") {
          e.preventDefault()
          close()
        }
      },
      [matches, active, choose, close],
    )

    const describedBy = ariaProps["aria-describedby"]

    return (
      <div className={`inputcn-field ${className ?? ""}`.trim()} {...containerProps}>
        {label === undefined ? null : (
          <label className="inputcn-label" htmlFor={id}>
            {label}
          </label>
        )}

        <div className="inputcn-relative">
          <div
            className="inputcn-group"
            data-invalid={ariaProps["aria-invalid"] ? "true" : undefined}
          >
            {renderCountry ? (
              renderCountry({ country, available, setCountry, disabled: rest.disabled })
            ) : (
              <>
                <button
                  ref={triggerRef}
                  type="button"
                  className="inputcn-country"
                  aria-haspopup="listbox"
                  aria-expanded={open}
                  aria-label={
                    country ? `Country: ${country.name}` : "Select country"
                  }
                  disabled={rest.disabled}
                  onClick={() => setOpen((o) => !o)}
                >
                  <span className="inputcn-iso">{country?.iso ?? "??"}</span>
                  <span className="inputcn-dial">+{country?.dial ?? ""}</span>
                  {CARET}
                </button>
                <span className="inputcn-divider" aria-hidden="true" />
              </>
            )}

            <input
              {...inputProps}
              {...ariaProps}
              id={id}
              className="inputcn-bare"
              aria-label={rest["aria-label"]}
              aria-labelledby={rest["aria-labelledby"]}
            />
          </div>

          {open ? (
            <div className="inputcn-popover">
              <div className="inputcn-popover-search">
                {/* eslint-disable-next-line jsx-a11y/no-autofocus -- focus belongs here on open */}
                <input
                  autoFocus
                  value={query}
                  onChange={(e) => {
                    setQuery(e.currentTarget.value)
                    setActive(0)
                  }}
                  onKeyDown={onSearchKeyDown}
                  placeholder="Search country…"
                  aria-label="Search country"
                  aria-controls={`${id}-country-list`}
                  autoComplete="off"
                />
              </div>
              <ul
                className="inputcn-popover-list"
                role="listbox"
                aria-label="Countries"
                id={`${id}-country-list`}
              >
                {matches.length === 0 ? (
                  <li className="inputcn-popover-empty" role="presentation">
                    No country found.
                  </li>
                ) : (
                  matches.map((c, i) => (
                    <li key={c.iso} role="presentation">
                      <button
                        type="button"
                        role="option"
                        aria-selected={c.iso === country?.iso}
                        className="inputcn-popover-item"
                        data-active={i === active ? "true" : undefined}
                        onMouseEnter={() => setActive(i)}
                        onClick={() => choose(c.iso)}
                      >
                        <span className="inputcn-iso">{c.iso}</span>
                        <span className="inputcn-name">{c.name}</span>
                        <span className="inputcn-dial">+{c.dial}</span>
                      </button>
                    </li>
                  ))
                )}
              </ul>
            </div>
          ) : null}
        </div>

        {sideEffect ? (
          <p className="inputcn-notice" role="status">
            {sideEffect.label}
            <button type="button" onClick={undoPaste} className="inputcn-undo">
              Undo
            </button>
            <button
              type="button"
              onClick={dismissSideEffect}
              className="inputcn-dismiss"
              aria-label="Dismiss"
            >
              ×
            </button>
          </p>
        ) : null}

        {ownsErrorUI && errorText ? (
          <p
            id={errorId}
            className={visible?.warning ? "inputcn-warning" : "inputcn-error"}
            // Stable rule name so a test can assert WHICH rule failed rather
            // than matching copy, which breaks on a rewrite or a locale change.
            data-rule={visible?.rule}
            role="alert"
          >
            {errorText}
          </p>
        ) : hint !== undefined ? (
          <p className="inputcn-hint" id={describedBy?.split(" ")[0]}>
            {hint}
          </p>
        ) : null}

        {hiddenInputProps ? <input {...hiddenInputProps} /> : null}
      </div>
    )
  },
)

"use client"

import { useCallback, useMemo, useRef, useState, type ClipboardEvent } from "react"

import { clipboardText } from "@inputcn/core/paste"
import { useField, type UseFieldResult } from "@inputcn/core/use-field"
import { useMaskedValue } from "@inputcn/core/use-masked-value"
import { custom, required as requiredRule, rules } from "@inputcn/core/validity"
import type { BaseFieldProps, Rule } from "@inputcn/core/types"

import { countryByIso, filterCountries, type Country } from "./countries"
import {
  formatNational,
  fromE164,
  isMobile,
  isValidLength,
  maxLengthOf,
  parseNational,
  parsePastedPhone,
  toE164,
} from "./phone"

export interface PhoneConstraints {
  /** Restrict the selector and reject numbers outside the list. */
  countries?: readonly string[]
  /** Reject numbers that look like landlines. */
  mobileOnly?: boolean
  /** Country selected before the user picks one. Defaults to "US". */
  defaultCountry?: string
}

export interface UsePhoneInputOptions
  extends BaseFieldProps<string>,
    PhoneConstraints {}

export interface UsePhoneInputResult extends UseFieldResult<string> {
  country: Country | undefined
  /** Countries offered in the selector, honouring `countries`. */
  available: readonly Country[]
  setCountry: (iso: string) => void
  /** Spread onto the visible <input>. */
  inputProps: {
    ref: React.RefObject<HTMLInputElement | null>
    onChange: (e: React.ChangeEvent<HTMLInputElement>) => void
    defaultValue: string
    onPaste: (e: ClipboardEvent<HTMLInputElement>) => void
    inputMode: "tel"
    autoComplete: "tel-national"
    type: "tel"
    placeholder: string | undefined
    disabled: boolean | undefined
    readOnly: boolean | undefined
  }
  /** Set when the last paste changed country. Must be shown and be undoable. */
  sideEffect: { from: string; to: string; label: string } | null
  dismissSideEffect: () => void
  /** Reverts the last paste, including the country switch. */
  undoPaste: () => void
}

const EMPTY = ""

export function usePhoneInput(options: UsePhoneInputOptions): UsePhoneInputResult {
  const {
    countries,
    mobileOnly,
    defaultCountry = "US",
    required,
    validate,
    disabled,
    readOnly,
    placeholder,
    ...base
  } = options

  const available = useMemo(() => filterCountries(countries), [countries])

  /* ---------------- country: derived from value, overridable ---------------- */

  // The country the user explicitly picked. `null` means "follow the value".
  const [picked, setPicked] = useState<string | null>(null)

  const incoming = base.value ?? base.defaultValue ?? EMPTY
  const parsedIncoming = useMemo(
    () => fromE164(incoming, countryByIso(defaultCountry)),
    [incoming, defaultCountry],
  )

  const country =
    countryByIso(picked ?? undefined) ??
    parsedIncoming.country ??
    countryByIso(defaultCountry) ??
    available[0]

  /* ---------------- validation rules ---------------- */

  const allowedIso = useMemo(
    () => (countries ? new Set(available.map((c) => c.iso)) : null),
    [countries, available],
  )

  const ruleList = useMemo<ReadonlyArray<Rule<string>>>(() => {
    return rules<string>(
      requiredRule<string>(required),
      {
        rule: "phoneFormat",
        test: (v) => {
          const p = fromE164(v, country)
          return isValidLength(p.national, p.country)
        },
      },
      allowedIso && {
        rule: "phoneAllowedCountries",
        params: { countries: available.map((c) => c.iso).join(", ") },
        test: (v) => {
          const p = fromE164(v, country)
          return !p.country || allowedIso.has(p.country.iso)
        },
      },
      mobileOnly && {
        rule: "phoneMobileOnly",
        test: (v) => {
          const p = fromE164(v, country)
          return isMobile(p.national, p.country)
        },
      },
      custom<string>(validate),
    )
  }, [required, country, allowedIso, available, mobileOnly, validate])

  const field = useField<string>({
    component: "PhoneInput",
    emptyValue: EMPTY,
    rules: ruleList,
    ...base,
    required,
    disabled,
    readOnly,
  })

  const { value, setValue } = field

  /* ---------------- masked display ---------------- */

  const format = useCallback(
    (e164: string) => formatNational(fromE164(e164, country).national, country),
    [country],
  )

  const parse = useCallback(
    (text: string) => toE164(parseNational(text, country), country),
    [country],
  )

  const masked = useMaskedValue<string>({
    value,
    format,
    parse,
    onChange: setValue,
    disabled,
    readOnly,
  })

  /* ---------------- country switching ---------------- */

  const setCountry = useCallback(
    (iso: string) => {
      const next = countryByIso(iso)
      if (!next) return
      setPicked(next.iso)
      // Keep the digits the user already typed; re-key them to the new country.
      const national = fromE164(value, country).national.slice(0, maxLengthOf(next))
      setValue(toE164(national, next))
    },
    [value, country, setValue],
  )

  /* ---------------- smart paste (PRD §11.2) ---------------- */

  const [sideEffect, setSideEffect] = useState<UsePhoneInputResult["sideEffect"]>(null)
  const undoRef = useRef<{ value: string; iso: string | null } | null>(null)

  const onPaste = useCallback(
    (e: ClipboardEvent<HTMLInputElement>) => {
      if (disabled || readOnly) return
      const text = clipboardText(e)
      if (!text) return
      e.preventDefault()

      const result = parsePastedPhone(text, country)
      undoRef.current = { value, iso: picked }

      if (result.switchedTo) {
        setPicked(result.switchedTo.iso)
        setSideEffect({
          from: country?.iso ?? "—",
          to: result.switchedTo.iso,
          label: `Switched to ${result.switchedTo.name}`,
        })
      } else {
        setSideEffect(null)
      }

      setValue(toE164(result.national, result.country ?? country))
    },
    [disabled, readOnly, country, value, picked, setValue],
  )

  const dismissSideEffect = useCallback(() => setSideEffect(null), [])

  const undoPaste = useCallback(() => {
    const prev = undoRef.current
    if (!prev) return
    setPicked(prev.iso)
    setValue(prev.value)
    setSideEffect(null)
    undoRef.current = null
  }, [setValue])

  const inputProps = useMemo(
    () => ({
      ...masked.inputProps,
      onPaste,
      inputMode: "tel" as const,
      autoComplete: "tel-national" as const,
      type: "tel" as const,
      placeholder: placeholder ?? country?.mask.replace(/#/g, "0"),
      disabled,
      readOnly,
    }),
    [masked.inputProps, onPaste, placeholder, country, disabled, readOnly],
  )

  return {
    ...field,
    country,
    available,
    setCountry,
    inputProps,
    sideEffect,
    dismissSideEffect,
    undoPaste,
  }
}

/**
 * Phone parsing, formatting and validation. Framework-free so it can run on
 * the server (`@inputcn/phone/phone`) and inside tests without React.
 *
 * Canonical value is always E.164: "+" followed by country code and national
 * significant number, no separators. The formatted string never escapes.
 */

import { digitsOf, scrub, splitExtension } from "@inputcn/core/paste"
import { formatMask } from "@inputcn/core/mask"

import { countryByDial, countryByIso, type Country } from "./countries"

export interface ParsedPhone {
  /** E.164, or "" when there are no digits. */
  e164: string
  /** National significant number, trunk prefix stripped. */
  national: string
  country: Country | undefined
  extension?: string
}

/** True when the national number has a length this country accepts. */
export function isValidLength(national: string, country: Country | undefined): boolean {
  if (!country) return false
  return country.lengths.includes(national.length)
}

/** True when the national number looks like a mobile line. */
export function isMobile(national: string, country: Country | undefined): boolean {
  const prefixes = country?.mobilePrefixes
  // Without data we cannot claim a number is NOT mobile, so we do not block it.
  if (!prefixes || prefixes.length === 0) return true
  for (const p of prefixes) {
    if (national.startsWith(p)) return true
  }
  return false
}

/** Strip a national trunk prefix ("0" in GB/DE/FR/…) if present. */
export function stripTrunk(national: string, country: Country | undefined): string {
  const trunk = country?.trunk
  if (trunk && national.length > trunk.length && national.startsWith(trunk)) {
    return national.slice(trunk.length)
  }
  return national
}

/** Format a national number using the country's template. */
export function formatNational(national: string, country: Country | undefined): string {
  if (!country) return national
  return formatMask(national.slice(0, maxLengthOf(country)), country.mask)
}

export function maxLengthOf(country: Country | undefined): number {
  if (!country) return 15 // E.164 hard ceiling
  let n = 0
  for (const l of country.lengths) if (l > n) n = l
  return n
}

/**
 * Keep only digits the country's template can hold.
 *
 * Order matters: the trunk prefix is stripped BEFORE the length cap, because
 * it is not part of the national significant number. Capping first would let
 * GB's leading "0" consume a mask slot and silently drop the final digit.
 */
export function parseNational(text: string, country: Country | undefined): string {
  const digits = digitsOf(text)
  if (!country) return digits.slice(0, 15)
  return stripTrunk(digits, country).slice(0, maxLengthOf(country))
}

/** Build E.164 from a country and its national number. */
export function toE164(national: string, country: Country | undefined): string {
  if (!national) return ""
  if (!country) return `+${national}`
  return `+${country.dial}${national}`
}

/**
 * Split an E.164 string back into country + national parts.
 * Tolerant of a missing "+" so stored values from other systems still load.
 */
export function fromE164(e164: string, fallback?: Country): ParsedPhone {
  const digits = digitsOf(e164)
  if (!digits) return { e164: "", national: "", country: fallback }

  const country = e164.trim().startsWith("+")
    ? countryByDial(digits)
    : (fallback ?? countryByDial(digits))

  if (!country) return { e164: `+${digits}`, national: digits, country: undefined }

  const national = digits.startsWith(country.dial)
    ? digits.slice(country.dial.length)
    : digits

  return { e164: toE164(national, country), national, country }
}

/**
 * Smart paste. PRD §11.2.
 *
 * Handles the messy reality: "Call me at (415) 555-2671 ext 4", a bare
 * international number, a number with the country's trunk prefix, or a
 * spreadsheet cell with stray whitespace.
 *
 * Returns `switchedTo` when the paste implies a DIFFERENT country than the one
 * currently selected — the caller must surface that, because it is a side
 * effect beyond this field's own value.
 */
export function parsePastedPhone(
  input: string,
  current: Country | undefined,
): { national: string; country: Country | undefined; extension?: string; switchedTo?: Country } {
  const cleaned = scrub(input)
  const { base, extension } = splitExtension(cleaned)
  const digits = digitsOf(base)

  if (!digits) return { national: "", country: current }

  // An explicit "+" (or a 00 IDD prefix) means the text carries its own country.
  const hasPlus = base.includes("+")
  const idd = digits.startsWith("00") ? digits.slice(2) : null
  const international = hasPlus ? digits : idd

  if (international) {
    const detected = countryByDial(international)
    if (detected) {
      const national = international.slice(detected.dial.length)
      return {
        national: national.slice(0, maxLengthOf(detected)),
        country: detected,
        extension,
        ...(detected.iso !== current?.iso ? { switchedTo: detected } : {}),
      }
    }
    return { national: international.slice(0, 15), country: undefined, extension }
  }

  // No country marker: treat the digits as national for the current country,
  // dropping a leading dial code if the user pasted it without a "+".
  let national = digits
  if (current && national.length > maxLengthOf(current) && national.startsWith(current.dial)) {
    national = national.slice(current.dial.length)
  }
  national = stripTrunk(national, current)
  return { national: national.slice(0, maxLengthOf(current)), country: current, extension }
}

/**
 * Country metadata for PhoneInput.
 *
 * Deliberately self-contained: no libphonenumber-js at this layer. The full
 * metadata bundle is ~145 kB and most apps need a dozen countries, so the
 * component ships national templates and defers *authoritative* validation to
 * an optional adapter (see `validator.ts`). PRD §8.4: one small dependency per
 * component, and only when genuinely needed.
 */

export interface Country {
  /** ISO 3166-1 alpha-2. */
  iso: string
  name: string
  /** Calling code without "+". */
  dial: string
  /** National-format template; `#` is a digit slot. */
  mask: string
  /** Expected national significant number length(s). */
  lengths: readonly number[]
  /** Leading digits that indicate a mobile line, for `mobileOnly`. */
  mobilePrefixes?: readonly string[]
  /** National trunk prefix stripped when parsing, e.g. "0" in the UK. */
  trunk?: string
}

export const COUNTRIES: readonly Country[] = [
  { iso: "US", name: "United States", dial: "1", mask: "(###) ###-####", lengths: [10] },
  { iso: "CA", name: "Canada", dial: "1", mask: "(###) ###-####", lengths: [10] },
  {
    iso: "GB",
    name: "United Kingdom",
    dial: "44",
    mask: "#### ######",
    lengths: [10],
    trunk: "0",
    mobilePrefixes: ["7"],
  },
  {
    iso: "IN",
    name: "India",
    dial: "91",
    mask: "##### #####",
    lengths: [10],
    trunk: "0",
    mobilePrefixes: ["6", "7", "8", "9"],
  },
  {
    iso: "DE",
    name: "Germany",
    dial: "49",
    mask: "### ########",
    lengths: [10, 11],
    trunk: "0",
    mobilePrefixes: ["15", "16", "17"],
  },
  {
    iso: "FR",
    name: "France",
    dial: "33",
    mask: "# ## ## ## ##",
    lengths: [9],
    trunk: "0",
    mobilePrefixes: ["6", "7"],
  },
  {
    iso: "ES",
    name: "Spain",
    dial: "34",
    mask: "### ## ## ##",
    lengths: [9],
    mobilePrefixes: ["6", "7"],
  },
  {
    iso: "IT",
    name: "Italy",
    dial: "39",
    mask: "### ### ####",
    lengths: [9, 10],
    mobilePrefixes: ["3"],
  },
  {
    iso: "NL",
    name: "Netherlands",
    dial: "31",
    mask: "# ########",
    lengths: [9],
    trunk: "0",
    mobilePrefixes: ["6"],
  },
  {
    iso: "JP",
    name: "Japan",
    dial: "81",
    mask: "##-####-####",
    lengths: [10],
    trunk: "0",
    mobilePrefixes: ["70", "80", "90"],
  },
  {
    iso: "BR",
    name: "Brazil",
    dial: "55",
    mask: "## #####-####",
    lengths: [10, 11],
    mobilePrefixes: ["9"],
  },
  {
    iso: "AU",
    name: "Australia",
    dial: "61",
    mask: "# #### ####",
    lengths: [9],
    trunk: "0",
    mobilePrefixes: ["4"],
  },
  {
    iso: "SG",
    name: "Singapore",
    dial: "65",
    mask: "#### ####",
    lengths: [8],
    mobilePrefixes: ["8", "9"],
  },
  {
    iso: "AE",
    name: "United Arab Emirates",
    dial: "971",
    mask: "## ### ####",
    lengths: [9],
    trunk: "0",
    mobilePrefixes: ["50", "52", "54", "55", "56", "58"],
  },
  {
    iso: "ZA",
    name: "South Africa",
    dial: "27",
    mask: "## ### ####",
    lengths: [9],
    trunk: "0",
    mobilePrefixes: ["6", "7", "8"],
  },
  {
    iso: "MX",
    name: "Mexico",
    dial: "52",
    mask: "## #### ####",
    lengths: [10],
    mobilePrefixes: ["1"],
  },
  {
    iso: "NG",
    name: "Nigeria",
    dial: "234",
    mask: "### ### ####",
    lengths: [10],
    trunk: "0",
    mobilePrefixes: ["70", "80", "81", "90", "91"],
  },
  {
    iso: "PK",
    name: "Pakistan",
    dial: "92",
    mask: "### #######",
    lengths: [10],
    trunk: "0",
    mobilePrefixes: ["3"],
  },
] as const

/* ------------------------------------------------------------------ *
 * Index maps. Built once at module load — every lookup is O(1) rather
 * than a .find() scan per keystroke (js-index-maps).
 * ------------------------------------------------------------------ */

export const BY_ISO: ReadonlyMap<string, Country> = new Map(
  COUNTRIES.map((c) => [c.iso, c]),
)

/** Dial codes longest-first, so "1" never shadows "1-something". */
const DIALS_BY_LENGTH: readonly Country[] = [...COUNTRIES].sort(
  (a, b) => b.dial.length - a.dial.length,
)

export function countryByIso(iso: string | undefined): Country | undefined {
  return iso ? BY_ISO.get(iso.toUpperCase()) : undefined
}

/**
 * Best country for a set of digits that begin with a calling code.
 * Longest match wins; ties resolve to the first declared country, which is
 * why US precedes CA in the list above (both are +1).
 */
export function countryByDial(digits: string): Country | undefined {
  for (const c of DIALS_BY_LENGTH) {
    if (digits.startsWith(c.dial)) return c
  }
  return undefined
}

/** Restrict the list, preserving the caller's ordering when given. */
export function filterCountries(allowed?: readonly string[]): readonly Country[] {
  if (!allowed || allowed.length === 0) return COUNTRIES
  const wanted = new Set(allowed.map((c) => c.toUpperCase()))
  const out: Country[] = []
  for (const iso of allowed) {
    const c = BY_ISO.get(iso.toUpperCase())
    if (c) out.push(c)
  }
  // Anything unrecognised is simply absent rather than throwing — a typo in a
  // country list should not blank the whole selector.
  return out.length > 0 ? out : COUNTRIES.filter((c) => wanted.has(c.iso))
}
